<script lang="ts">
  import AuditValue from '../components/AuditValue.svelte';
  import DataTable from '../components/DataTable.svelte';
  import StatTile from '../components/StatTile.svelte';
  import TrendChart from '../components/TrendChart.svelte';
  import { formatDate, formatNumber } from '../lib/format';
  import type { HouseDetail, Overview, TrendPayload } from '../lib/types';

  export let detail: HouseDetail;
  export let overview: Overview;
  export let trend: TrendPayload;

  type HistoryRow = {
    year: number; turn: number; days_to_election: number; sample_size: number; mode: string;
    published: Record<string, number>; official: Record<string, number>; bias: Record<string, number>;
    mae: number; rmse: number; margin_error: number; expected_mae: number; pm: number;
    decomposition: Record<string, number>; evidence_id: string; run_id: string;
  };
  type HousePollRow = {
    registration_no: string; field_end: string; sample_size: number; mode: string; base: string;
    included: boolean; reason_code: string; evidence_id: string; run_id: string;
  };

  $: historyRows = detail.history as unknown as HistoryRow[];
  $: pollRows = detail.polls as unknown as HousePollRow[];
  $: houseTrend = trend.points.filter((point) => point.institute_id === detail.house.id);
  $: topPublished = detail.house.published.slice(0, 4);
  $: topAdjusted = detail.house.adjusted.slice(0, 4);
  $: topProjection = detail.house.projection.slice(0, 2);
  $: topAggregate = overview.nowcast.slice(0, 2);
  $: candidateById = new Map(overview.candidates.map((candidate) => [candidate.id, candidate]));

  function candidateValues(values: Record<string, number>): string {
    return Object.entries(values).map(([id, value]) => `${candidateById.get(id)?.short_name ?? id} ${formatNumber(value)}%`).join(' · ');
  }
</script>

<section class="page-stack" aria-labelledby="house-title">
  <nav class="breadcrumb" aria-label="Breadcrumb">
    <a href="/institutos" data-route>Institutos</a><span aria-hidden="true">/</span><span aria-current="page">{detail.house.name}</span>
  </nav>

  <header class="page-hero compact-hero">
    <p class="eyebrow">Ficha auditável · {detail.house.mode}</p>
    <h1 id="house-title">{detail.house.name}</h1>
    <p>
      Última entrada: {formatDate(detail.house.latest_poll.field_start)}–{formatDate(detail.house.latest_poll.field_end)} ·
      <span data-kind="Publicado" data-value={detail.house.latest_poll.sample_size} data-run-id={detail.house.latest_poll.run_id} data-evidence={detail.house.latest_poll.evidence_id}>n={detail.house.latest_poll.sample_size.toLocaleString('pt-BR')}</span> ·
      {detail.house.latest_poll.registration_no} · base: válidos.
    </p>
    <a href={`/pesquisas?casa=${detail.house.id}`} data-route>Todas as pesquisas desta casa →</a>
  </header>

  <div class="stat-grid" aria-label="Quatro leituras da casa">
    <StatTile kind="Publicado" icon="▤" items={topPublished} candidates={overview.candidates} note={`Campo até ${formatDate(detail.house.latest_poll.field_end)} · margem declarada ±${formatNumber(detail.house.latest_poll.margin_of_error)} p.p.`} />
    <StatTile kind="Ajustada" icon="⇄" items={topAdjusted} candidates={overview.candidates} note="Remove o desvio estimado desta casa em relação ao conjunto; com pouca observação, o ajuste encolhe." />
    <StatTile kind="Projeção" icon="◎" items={topProjection} candidates={overview.candidates} note="Aplica a mesma incerteza histórica e mudança até a urna usadas no agregado." projectionWarning={detail.projection_warning} />
    <StatTile kind="Estimativa agregada de hoje" icon="◉" items={topAggregate} candidates={overview.candidates} note="Referência do conjunto das casas nesta execução." />
  </div>

  <section class="content-section" aria-labelledby="history-title">
    <div class="section-heading">
      <div><p class="eyebrow">Contexto, não placar</p><h2 id="history-title">Erro histórico</h2></div>
      <p>Véspera sintética por eleição e turno; resultado e decomposição ficam lado a lado.</p>
    </div>
    <DataTable label={`Erro histórico de ${detail.house.name}`}>
      <table>
        <thead><tr><th>Eleição/turno</th><th>Contexto</th><th>Publicado</th><th>Oficial</th><th>Diferença</th><th class="num">Erro margem</th><th class="num">MAE</th><th class="num">Esperado</th><th>Decomposição</th></tr></thead>
        <tbody>
          {#each historyRows as row}
            <tr>
              <th scope="row">{row.year} · {row.turn}º turno</th>
              <td>D-{row.days_to_election} · <span data-value={row.sample_size} data-kind="Erro histórico" data-run-id={row.run_id} data-evidence={row.evidence_id}>n={row.sample_size.toLocaleString('pt-BR')}</span> · {row.mode}</td>
              <td>{candidateValues(row.published)}</td>
              <td>{candidateValues(row.official)}</td>
              <td>{candidateValues(row.bias)}</td>
              <td class="num" data-value={row.margin_error} data-kind="Erro histórico" data-run-id={row.run_id} data-evidence={row.evidence_id}>{row.margin_error > 0 ? '+' : ''}{formatNumber(row.margin_error)} p.p.</td>
              <td class="num" data-value={row.mae} data-kind="Erro histórico" data-run-id={row.run_id} data-evidence={row.evidence_id}>{formatNumber(row.mae)} p.p.</td>
              <td class="num" data-value={row.expected_mae} data-kind="Erro histórico" data-run-id={row.run_id} data-evidence={row.evidence_id}>{formatNumber(row.expected_mae)} p.p.</td>
              <td><div class="decomposition" aria-label="Decomposição sintética do erro">{#each Object.entries(row.decomposition) as [key, value]}<span style={`--part:${Math.min(100, value * 22)}%`} title={`${key}: ${formatNumber(value)} p.p.`}></span>{/each}</div></td>
            </tr>
          {/each}
        </tbody>
      </table>
    </DataTable>
    <p class="fixed-note">Em 2014–2022, o desempenho de uma casa em uma eleição pouco previu a seguinte; por isso o histórico entra com peso limitado. Nesta ficha, o histórico é sintético.</p>
  </section>

  <section class="content-section" aria-labelledby="house-trend-title">
    <div class="section-heading"><div><p class="eyebrow">Casa × conjunto</p><h2 id="house-trend-title">Tendência ajustada desta casa</h2></div><p>Pontos com evidência e tabela-gêmea.</p></div>
    <TrendChart points={houseTrend} candidates={overview.candidates} title={`Tendência ajustada de ${detail.house.name}`} />
  </section>

  <div class="detail-grid">
    <section class="content-card" aria-labelledby="method-house-title">
      <p class="eyebrow">Ficha do registro</p>
      <h2 id="method-house-title">Metodologia declarada</h2>
      <dl class="definition-list">
        <div><dt>Modo</dt><dd>{detail.methodology.mode}</dd></div>
        <div><dt>Metodologia</dt><dd>{detail.methodology.methodology_text}</dd></div>
        <div><dt>Plano amostral</dt><dd>{detail.methodology.sample_plan_text}</dd></div>
        <div><dt>Responsável</dt><dd>{detail.methodology.statistician}</dd></div>
        <div><dt>Contratante</dt><dd>{detail.methodology.article_10.contractor}</dd></div>
        <div><dt>Registro</dt><dd>{detail.methodology.article_10.registration_number}</dd></div>
      </dl>
      <a href="/evidence/demo-catalog.txt">Abrir evidência {detail.methodology.evidence_id} →</a>
    </section>

    <section class="content-card" aria-labelledby="weight-title">
      <p class="eyebrow">Peso</p>
      <h2 id="weight-title">Participação no agregado</h2>
      <AuditValue metric={detail.house.weight} showRange={false} />
      <div class="weight-total" aria-label={`Peso total ${formatNumber(detail.house.weight.q50)}%`}><span style={`width:${Math.min(100, detail.house.weight.q50)}%`}></span></div>
      <dl class="weight-components">
        {#each [['Tempo', detail.weight_components.time], ['Amostra', detail.weight_components.sample], ['Modo', detail.weight_components.mode], ['Casa', detail.weight_components.house], ['Huber', detail.weight_components.huber]] as component}
          <div><dt>{component[0]}</dt><dd data-value={component[1]} data-kind="Peso" data-run-id={detail.weight_components.run_id} data-evidence={detail.weight_components.evidence_id}>{formatNumber(Number(component[1]))}×</dd></div>
        {/each}
      </dl>
      <p>Multiplicação dos componentes, seguida de normalização e cap de 25% por casa.</p>
    </section>
  </div>

  <section class="content-section" aria-labelledby="house-polls-title">
    <div class="section-heading"><div><p class="eyebrow">Rastreabilidade</p><h2 id="house-polls-title">Pesquisas desta casa</h2></div></div>
    <DataTable label={`Pesquisas de ${detail.house.name}`} compact>
      <table>
        <thead><tr><th>Campo</th><th>Registro</th><th class="num">n</th><th>Modo/base</th><th>Decisão</th><th>Evidência</th></tr></thead>
        <tbody>{#each pollRows as poll}<tr><td>{formatDate(poll.field_end)}</td><td><code>{poll.registration_no}</code></td><td class="num" data-value={poll.sample_size} data-kind="Publicado" data-run-id={poll.run_id} data-evidence={poll.evidence_id}>{poll.sample_size.toLocaleString('pt-BR')}</td><td>{poll.mode} · {poll.base}</td><td><span class:included={poll.included} class="decision-chip">{poll.included ? 'Incluída' : 'Fora'} · {poll.reason_code}</span></td><td><a href="/evidence/demo-catalog.txt">{poll.evidence_id}</a></td></tr>{/each}</tbody>
      </table>
    </DataTable>
  </section>
</section>
